package com.smartbus.academic.controller;
import com.smartbus.academic.dto.AcademicSectionRequest; import com.smartbus.academic.entity.*; import com.smartbus.academic.repository.AcademicSectionRepository; import jakarta.validation.Valid; import jakarta.validation.constraints.DecimalMax; import jakarta.validation.constraints.DecimalMin; import java.time.Instant; import java.util.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException;
@RestController @RequestMapping("/api/hod/academic") public class AcademicAttendanceController { private final AcademicSectionRepository sections; public AcademicAttendanceController(AcademicSectionRepository sections){this.sections=sections;}
 @GetMapping("/sections") public List<AcademicSection> list(@RequestParam(required=false) Integer year){return year==null?sections.findAllByOrderByAcademicYearAscSpecializationAscSectionNumberAsc():sections.findByAcademicYearOrderBySpecializationAscSectionNumberAsc(year);}
 @PostMapping("/sections") public ResponseEntity<AcademicSection> create(@Valid @RequestBody AcademicSectionRequest input){ AcademicSection section=new AcademicSection();section.id=UUID.randomUUID();section.academicYear=input.academicYear();section.specialization=input.specialization();section.sectionNumber=input.sectionNumber();section.createdAt=Instant.now();for(var item:input.students()){AcademicRosterStudent student=new AcademicRosterStudent();student.id=UUID.randomUUID();student.section=section;student.studentName=item.name();student.rollNumber=item.rollNumber();student.attendancePercent=item.attendancePercent();section.students.add(student);}return ResponseEntity.status(HttpStatus.CREATED).body(sections.save(section));}
 @PatchMapping("/students/{studentId}/attendance") public AcademicRosterStudent updateAttendance(@PathVariable UUID studentId,@RequestParam @DecimalMin("0") @DecimalMax("100") double percentage){for(var section:sections.findAllByOrderByAcademicYearAscSpecializationAscSectionNumberAsc())for(var student:section.students)if(student.id.equals(studentId)){student.attendancePercent=percentage;sections.save(section);return student;}throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Academic roster student not found");}
}
